using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using Rootborn.UI.Modern;using Rootborn.Game.Common;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryCategoryArtTests{
[TestCase("toolbox","inventory-tools")][TestCase("water_bottle","inventory-consumables")][TestCase("folder","inventory-misc")]public void CategoryUsesCrispSavedSpriteAndThemeDependency(string name,string key){var path="Assets/Art/UI/UrbanMolding/"+name+".png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(64,64)));Assert.That(s.pivot,Is.EqualTo(new Vector2(32,32)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)).address,Is.EqualTo("sprites/ui/urban-life/"+name.Replace('_','-')));Assert.That(AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset").GetIcon(key),Is.SameAs(s));}
[Test]public void AllFourTabsUseSharedIconOwnerAndExistingHitTargets(){var go=new GameObject("Inventory",typeof(RectTransform));try{go.AddComponent<ModernUiInventoryPanel>().Show();var keys=new[]{"inventory-all","inventory-tools","inventory-consumables","inventory-misc"};for(int i=0;i<4;i++){var tab=go.transform.Find("Tab_"+i);var icon=tab.Find("Icon");Assert.That(icon.GetComponent<UrbanUiIcon>(),Is.Not.Null);Assert.That(new SerializedObject(icon.GetComponent<UrbanUiIcon>()).FindProperty("_key").stringValue,Is.EqualTo(keys[i]));Assert.That(((RectTransform)icon).sizeDelta,Is.EqualTo(new Vector2(56,56)));Assert.That(tab.GetComponent<UnityEngine.UI.Button>(),Is.Not.Null);Assert.That(icon.GetComponent<UnityEngine.UI.Image>().raycastTarget,Is.False);}Assert.That(go.GetComponentsInChildren<UnityEngine.UI.ScrollRect>().Single().content.childCount,Is.EqualTo(Rootborn.Game.Common.Inventory.MaxSlots));}finally{Object.DestroyImmediate(go);}}
[TestCase("Allowance","urban_icon_money")][TestCase("FacilityMaterials","building_materials")]public void ExistingInventoryItemsHaveAuthoredIconsWithoutChangingEconomy(string file,string sprite){var a=AssetDatabase.LoadAssetAtPath<ItemDefinition>("Assets/Data/Items/Item_"+file+".asset");Assert.That(a.Icon,Is.Not.Null);Assert.That(a.Icon.name,Is.EqualTo(sprite));Assert.That(a.MaxStack,Is.EqualTo(9999));Assert.That(a.Icon.texture.filterMode,Is.EqualTo(FilterMode.Point));}
}}
